// InventoryFilter provides filtering for Inventory queries
type InventoryFilter struct {
	Id          *UUIDFilter
	Title       *StringFilter
	PriceCents  *Int64Filter
	ReorderAt   *Int64Filter
	StockOnHand *Int64Filter
	StockHeld   *Int64Filter
	Version     *Int64Filter
	// ReferencedByCheckoutWrap filters on the presence or absence of a
	// Checkout whose wrap points at this row.
	ReferencedByCheckoutWrap *ReferencedByFilter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []InventoryFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []InventoryFilter
}

// InventoryUpdate provides fields that can be updated
type InventoryUpdate struct {
	Title            *string
	PriceCents       *types.GenericInt64
	ReorderAt        *types.GenericInt64
	ReorderAtSetNull bool
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewInventorySnapshotUpdate maps every mutable field from a complete
// Inventory value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewInventorySnapshotUpdate(input *types.Inventory) *InventoryUpdate {
	update := &InventoryUpdate{}
	if input == nil {
		return update
	}
	update.Title = &input.Title
	update.PriceCents = &input.PriceCents
	if input.ReorderAt == nil {
		update.ReorderAtSetNull = true
	} else {
		update.ReorderAt = input.ReorderAt
	}
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *InventoryUpdate) ApplyTo(row *types.Inventory) {
	if u == nil || row == nil {
		return
	}
	if u.Title != nil {
		row.Title = *u.Title
	}
	if u.PriceCents != nil {
		row.PriceCents = *u.PriceCents
	}
	if u.ReorderAtSetNull {
		row.ReorderAt = nil
	} else if u.ReorderAt != nil {
		row.ReorderAt = u.ReorderAt
	}
}

// InventoryFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
// FindMany's WHERE is them joined by AND. A nil filter has none.
func InventoryFilterConditions(filter *InventoryFilter, args *[]any) []string {
	return filter.conditions(args, len(*args))
}

// buildWhereClause builds a WHERE clause from a InventoryFilter: its
// conditions joined by AND, or nothing when it has none.
func (f *InventoryFilter) buildWhereClause(args *[]interface{}, paramOffset int) string {
	conditions := f.conditions(args, paramOffset)
	if len(conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(conditions, " AND ")
}

